def compute(vars):
    total_credit_lines = vars["v1"]
    available_credit_lines = vars["v2"]
    drawn_credit_lines = total_credit_lines - available_credit_lines

    return {
        "value": drawn_credit_lines,
        "trace": {
            "total_credit_lines": total_credit_lines,
            "available_credit_lines": available_credit_lines,
            "drawn_credit_lines": drawn_credit_lines,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
